it('renders a batch of each of the four documents and saves them for review', function () {
    Carbon::setTestNow(Carbon::parse('2026-09-15 11:20:00'));

    BulkDocumentAdminRoutes::wire(app());

    $settings = app(SettingsService::class);
    $settings->set('invoice_business_name', 'K Beauty Bliss Trading LLC');
    $settings->set('invoice_address', "Office 1902, Burlington Tower\nBusiness Bay, Dubai\nUnited Arab Emirates");
    $settings->set('invoice_trn', '100123456700003');
    $settings->set('invoice_email', 'info@kbeautybliss.com');
    $settings->set('invoice_phone', '+971 58 505 2611');
    $settings->set('invoice_website', 'kbeautybliss.com');
    $settings->set('invoice_footer', "Payment received in full — no further amount is due.");

    $orders = gcPreviewOrders();
    $ids = implode(',', array_map(fn (Order $o) => $o->id, $orders));

    test()->actingAs(AdminUser::create([
        'name' => 'Preview Owner',
        'email' => 'gc-preview-owner@example.test',
        'password' => 'secret-secret',
        'role' => 'owner',
    ]), 'admin');

    /*
     * THE INVOICE RUN IS LAST, AND THE ORDER IS PART OF WHAT THESE SHOW.
     * Printing a packing slip, a delivery note or a label allocates nothing, so
     * rendering those three first means their previews carry NO invoice
     * reference — which is the rule made visible. The invoice run then mints
     * one number per order, and a packing slip reprinted afterwards would show
     * it. Generating the invoice first would have put an invoice number on all
     * four previews and quietly hidden the distinction.
     */
    $files = [
        'packing-slip' => 'bulk-packing-slips.html',
        'delivery-note' => 'bulk-delivery-notes.html',
        'dispatch-label' => 'bulk-dispatch-labels.html',
        'invoice' => 'bulk-invoices.html',
    ];

    foreach ($files as $type => $name) {
        $html = (string) test()
            ->get('/admin-api/orders-bulk-documents?type=' . $type . '&ids=' . $ids)
            ->assertStatus(200)
            ->getContent();

        // FOUR SHEETS, EVERY TIME. The count is the assertion that matters: a
        // preview quietly missing an order would still look like a document.
        $class = $type === 'dispatch-label' ? 'class="sheet lbl"' : 'class="sheet"';

        expect(substr_count($html, $class))->toBe(4, $name . ' does not hold four sheets')
            ->and($html)->toContain('.bulkdoc > .sheet { break-after: page; page-break-after: always; }')
            ->and($html)->toContain('.bulkdoc > .sheet:last-child { break-after: auto; page-break-after: auto; }');

        foreach ($orders as $order) {
            expect($html)->toContain((string) $order->order_number);
        }

        file_put_contents(gcPreviewDir() . '/' . $name, $html);
    }

    // The Arabic order's INVOICE is Arabic; its packing slip is not. Read off
    // the two files that were just written, so the preview is what is asserted.
    $invoices = (string) file_get_contents(gcPreviewDir() . '/bulk-invoices.html');
    $slips = (string) file_get_contents(gcPreviewDir() . '/bulk-packing-slips.html');

    /*
     * dir IS NOT ASSERTED TO BE rtl, AND THAT IS THE CORRECT ANSWER TODAY.
     * Locale::direction() answers from the shop's SECOND switch, not from the
     * language: Arabic can be on while the mirrored layout is still being
     * built, which is the state this shop is in, so an Arabic sheet is
     * lang="ar" dir="ltr". document.blade.php's own header says the same thing
     * about the single documents. Pinning dir="rtl" here would pin a state the
     * shop is not in and would go red the day another lane turns mirroring on —
     * which is the day this should start reading rtl by itself.
     */
    expect(substr_count($invoices, 'lang="ar"'))->toBe(1)
        ->and(substr_count($invoices, 'lang="en"'))->toBeGreaterThan(1)
        ->and(str_contains($slips, 'lang="ar"'))->toBeFalse();

    // The cash-on-delivery label carries its COLLECT box and the other three
    // labels do not — the one figure on a label that a driver acts on.
    $labels = (string) file_get_contents(gcPreviewDir() . '/bulk-dispatch-labels.html');

    expect(substr_count($labels, 'class="cod"'))->toBe(1);

    Carbon::setTestNow();
});
